"""Offline replay: transport registry, problem snapshots, event pipeline, restart.

Everything in this module is deterministic and finite.  One `CaseSession`
replays a single case:

* `configure` patches the cumulative topology/traffic state and resets the
  algorithm state (but never the transport history or the generation counter),
* `issue` freezes an immutable problem snapshot plus the solved proposal,
* `deliver` classifies a ticket as duplicate/obsolete/superseded/infeasible or
  accepts it into the barrier cache,
* `step` advances the cached controller only when the partial barrier permits
  progress,
* `save`/`restore` move the complete algorithm state across a generation
  boundary while tickets, proposals and receipts never roll back.
"""
import numpy as np
from typing import Any, Dict, List, Optional

from te.path_providers.base import PathProvider
from te.algorithms.communication.partial_barrier import PartialBarrier
from te.algorithms.formulations.path_based.distributed.coordinator import Coordinator
from te.algorithms.formulations.path_based.distributed.worker import solve_worker_proposal


class Ticket:
    """An immutable issued proposal."""
    __slots__ = ('sequence', 'worker', 'generation', 'bias', 'rho', 'proposal')

    def __init__(self, sequence, worker, generation, bias, rho, proposal):
        self.sequence = sequence
        self.worker = worker
        self.generation = generation
        self.bias = bias
        self.rho = rho
        self.proposal = proposal


class Transport:
    """Case scoped registry: tickets, receipts and checkpoints."""

    def __init__(self):
        self.tickets: Dict[int, Ticket] = {}
        self.receipts = set()
        self.checkpoints: Dict[int, Dict[str, Any]] = {}
        self.sequence = 0

    def issue_next(self, ticket_id, ticket):
        self.tickets[ticket_id] = ticket
        self.sequence += 1
        return ticket


class CaseSession:
    def __init__(self, case):
        self.case = case
        self.num_edges = len(case['edges'])
        self.E = self.num_edges
        self.num_nodes = case['nodes']
        self.owned = [[int(k) for k in row] for row in case['workers']]
        self.W = len(self.owned)
        self.quorum = int(case['quorum'])
        self.max_lag = int(case['max_lag'])
        a, b = case['relax']
        self.alpha = float(a) / float(b)
        self.transport = Transport()
        # ---------------------------------------------------------------- state
        self.generation = 0
        self.cap = np.array([int(e[2]) for e in case['edges']], dtype=np.float64)
        self.dem = np.array([int(c['demand']) for c in case['commodities']], dtype=np.float64)
        self.slots: List[List[Optional[tuple]]] = [
            [None if p is None else tuple(int(e) for e in p) for p in c['paths']]
            for c in case['commodities']]
        self.mode = case['mode']
        self.rho = int(case['rho'])
        self.provider = PathProvider.from_slots(self.E, self.slots)
        self.amounts: List[List[float]] = [[0.0] * len(row) for row in self.slots]
        self.barrier = PartialBarrier(self.W, self.quorum, self.max_lag, self.E)
        self.coord = Coordinator(self.E, self.rho, self.alpha)
        self._last_z = np.zeros(self.E)
        self._last_u = np.zeros(self.E)
        self.sync_controller()

    # ------------------------------------------------------------- controller
    @property
    def z(self):
        return self.coord.z

    @property
    def u(self):
        return self.coord.u

    def sync_controller(self):
        self._last_z = np.array(self.coord.z, dtype=np.float64, copy=True)
        self._last_u = np.array(self.coord.u, dtype=np.float64, copy=True)

    def rebuild_provider(self):
        self.provider = PathProvider.from_slots(self.E, self.slots)

    def reset_algorithm(self):
        """Initial zeros/absences; tickets, receipts and checkpoints persist."""
        self.amounts = [[0.0] * len(row) for row in self.slots]
        self.barrier.reset()
        self.coord.reset()
        self.sync_controller()

    # --------------------------------------------------------------- geometry
    def live_mask(self):
        return self.cap > 0.0

    def total_load(self) -> np.ndarray:
        """Raw per-edge totals S = sum_w A[w,:]."""
        if self.W == 0:
            return np.zeros(self.E)
        return self.barrier.storage.sum(axis=0)

    def utilization(self, totals: np.ndarray) -> np.ndarray:
        """Normalized utilization X[e] = S[e] / c[e], zero on withdrawn edges."""
        live = self.live_mask()
        out = np.zeros(self.E)
        if self.E:
            out[live] = totals[live] / self.cap[live]
        return out

    def bias_row(self, worker: int, X: np.ndarray) -> np.ndarray:
        live = self.live_mask()
        out = np.zeros(self.E)
        A = self.barrier.storage[worker]
        out[live] = A[live] / self.cap[live] \
            + (self._last_z[live] - X[live] - self._last_u[live]) / float(self.W)
        return out

    # ------------------------------------------------------------------ events
    def run(self) -> Dict[str, Any]:
        events = []
        for ev in self.case['events']:
            events.append(self.dispatch(ev))
        return {'events': events}

    def dispatch(self, ev) -> Dict[str, Any]:
        op = ev['op']
        if op == 'configure':
            return self.event_configure(ev)
        if op == 'issue':
            return self.event_issue(ev)
        if op == 'deliver':
            return self.event_deliver(ev)
        if op == 'step':
            return self.event_step(ev)
        if op == 'retune':
            return self.event_retune(ev)
        if op == 'save':
            return self.event_save(ev)
        if op == 'restore':
            return self.event_restore(ev)
        return self.event_audit(ev)

    def event_configure(self, ev):
        for edge_id, value in ev['capacity']:
            self.cap[int(edge_id)] = float(value)
        for commodity_id, value in ev['demand']:
            self.dem[int(commodity_id)] = float(value)
        for commodity_id, slot_id, path in ev['paths']:
            self.slots[int(commodity_id)][int(slot_id)] = \
                None if path is None else tuple(int(e) for e in path)
        self.mode = ev['mode']
        self.rebuild_provider()
        self.generation += 1
        self.reset_algorithm()
        return {'op': 'configure', 'generation': self.generation}

    def event_issue(self, ev):
        ticket_id = int(ev['id'])
        worker = int(ev['worker'])
        X = self.utilization(self.total_load())
        bias = self.bias_row(worker, X)
        proposal = solve_worker_proposal(self.owned[worker], self.cap, self.dem, self.slots,
                                         self.mode, float(self.rho), bias, self.E)
        ticket = Ticket(self.transport.sequence, worker, self.generation, bias, self.rho, proposal)
        self.transport.issue_next(ticket_id, ticket)
        return {'op': 'issue', 'id': ticket_id, 'worker': worker,
                'generation': self.generation, 'bias': [float(v) for v in bias],
                'rho': int(self.rho), 'result': proposal}

    def event_deliver(self, ev):
        ticket_id = int(ev['id'])
        ticket = self.transport.tickets[ticket_id]
        if ticket_id in self.transport.receipts:
            status = 'duplicate'
        elif ticket.generation != self.generation:
            status = 'obsolete'
        elif self.barrier.superseded(ticket.worker, ticket.sequence):
            status = 'superseded'
        elif ticket.proposal['status'] != 'optimal':
            status = 'infeasible'
        else:
            status = 'accepted'
            worker = ticket.worker
            loads = np.asarray([float(v) for v in ticket.proposal['edge_load']], dtype=np.float64)
            rows = ticket.proposal['flow']
            for i, k in enumerate(self.owned[worker]):
                self.amounts[k] = [float(v) for v in rows[i]]
            self.barrier.arrive(worker, loads, ticket.sequence)
        self.transport.receipts.add(ticket_id)
        return {'op': 'deliver', 'id': ticket_id, 'status': status}

    def event_step(self, ev):
        if not self.barrier.can_advance():
            missing, stale = self.barrier.blockers()
            return {'op': 'step', 'status': 'waiting', 'missing': missing,
                    'stale': stale, 'fresh': self.barrier.fresh()}
        live = self.live_mask()
        totals = self.total_load()
        X = self.utilization(totals)
        z, u, ceiling, pressure = self.coord.step(X, live, self.mode)
        self._last_z, self._last_u = np.array(z, copy=True), np.array(u, copy=True)
        self.barrier.advance()
        return {'op': 'step', 'status': 'advanced', 'round': int(self.barrier.clock),
                'load': [float(v) for v in totals], 'ceiling': float(ceiling),
                'z': [float(v) for v in z], 'dual': [float(v) for v in u],
                'pressure': [float(v) for v in pressure]}

    def event_retune(self, ev):
        new_rho = int(ev['rho'])
        self.coord.retune(float(new_rho))
        self.rho = new_rho
        self._last_z, self._last_u = np.array(self.coord.z, copy=True), np.array(self.coord.u, copy=True)
        return {'op': 'retune', 'rho': new_rho}

    def event_save(self, ev):
        name = int(ev['name'])
        self.transport.checkpoints[name] = self.snapshot()
        return {'op': 'save', 'name': name}

    def event_restore(self, ev):
        name = int(ev['name'])
        self.restore(self.transport.checkpoints[name])
        return {'op': 'restore', 'name': name, 'generation': self.generation}

    def event_audit(self, ev):
        totals = self.total_load()
        return {'op': 'audit', 'generation': self.generation,
                'round': int(self.barrier.clock), 'rho': int(self.rho),
                'flow': [[float(v) for v in row] for row in self.amounts],
                'worker_load': [[float(v) for v in row] for row in self.barrier.storage],
                'load': [float(v) for v in totals],
                'z': [float(v) for v in self._last_z], 'dual': [float(v) for v in self._last_u],
                'seen': self.barrier.seen(), 'fresh': self.barrier.fresh(),
                'age': self.barrier.ages()}

    # ----------------------------------------------------- checkpoint/restart
    def snapshot(self) -> Dict[str, Any]:
        return {'cap': self.cap.copy(), 'dem': self.dem.copy(),
                'slots': [list(row) for row in self.slots], 'mode': self.mode,
                'rho': self.rho, 'amounts': [list(row) for row in self.amounts],
                'barrier': self.barrier.state(),
                'controller': {'z': np.array(self._last_z, copy=True),
                               'u': np.array(self._last_u, copy=True),
                               'rho': self.rho}}

    def restore(self, saved: Dict[str, Any]):
        """Reinstate exactly the checkpointed state; the generation moves on."""
        self.cap = saved['cap'].copy()
        self.dem = saved['dem'].copy()
        self.slots = [list(row) for row in saved['slots']]
        self.mode = saved['mode']
        self.rho = saved['rho']
        self.rebuild_provider()
        self.amounts = [list(row) for row in saved['amounts']]
        self.barrier.load_state(saved['barrier'])
        state = saved['controller']
        self.coord.load_state({'Z': np.array(state['z'], copy=True),
                               'Z_old': np.array(state['z'], copy=True),
                               'dual': np.array(state['u'], copy=True),
                               'rho': state['rho'], 'iterate': 0})
        self._last_z = np.array(state['z'], copy=True)
        self._last_u = np.array(state['u'], copy=True)
        self.generation += 1


def run_case(case) -> Dict[str, Any]:
    """Replay one case into its per-event response."""
    return CaseSession(case).run()
PYEOF
